class Main {
    public static void main(String[] args) {
        Result r = new Result();
        r.setMark(60);
        r.setMark(-1);
        System.out.println(r.getMark());
    }
}
class Result {
    private int mark;
    public boolean setMark(int mark) {
        if (mark < 0 || mark > 100) {
            return false;
        }
        this.mark = mark;
        return true;
    }
    public int getMark() {
        return mark;
    }
}

