class Main {
    public static void main(String[] args) {
        int x = 3;
        Point p = new Point(x, 4);
        x = 9;
        System.out.println(p.x());
    }
}
final class Point {
    private final int x;
    private final int y;
    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
    public int x() {
        return x;
    }
    public int y() {
        return y;
    }
}
